[IO.File]::WriteAllText((Join-Path $PWD 'check.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh check.sh <mqtt port> <topic> <expected reading> [tries]`nport=`$1`ntopic=`$2`nexpected=`$3`ntries=`${4:-20}`ntry=0`nwhile :; do`n  # The broker sends the topic's length in two bytes, the topic, then the reading: keep what follows.`n  kept=`$(curl -s `"mqtt://127.0.0.1:`$port/`$topic`" | tail -c +`$(( `${#topic} + 3 )))`n  if [ `"`$kept`" = `"`$expected`" ]; then`n    echo `"ok: `$topic is `$kept`"`n    exit 0`n  fi`n  try=`$(( try + 1 ))`n  if [ `"`$try`" -ge `"`$tries`" ]; then`n    break`n  fi`n  sleep 0.5`ndone`nif [ -z `"`$kept`" ]; then`n  echo `"FAIL: nothing kept on `$topic`"`nelse`n  echo `"FAIL: `$topic is `$kept, expected `$expected`"`nfi`nexit 1`n")
